   end loop;
 end loop;
 return false;
end $moderation$;
revoke all on function private.contains_profanity(text) from public,anon,authenticated;

-- Preserve quoted incident evidence; flag it for staff instead of suppressing it.
create or replace function private.moderate_community_text() returns trigger
language plpgsql security definer set search_path='' as $$
declare fields text[]; field text; label text; old_row jsonb:=case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end; new_row jsonb:=to_jsonb(new);
begin
 if tg_table_name='incident_reports' and (tg_op='INSERT' or new_row->>'description' is distinct from old_row->>'description') then
   new.language_flagged:=private.contains_profanity(new_row->>'description');
 elsif tg_table_name='community_case_updates' and new_row->>'entry_type'='resident_follow_up' then
   new.language_flagged:=private.contains_profanity(new_row->>'message'); return new;
 end if;
 fields:=case tg_table_name when 'boarding_messages' then array['body'] when 'resident_feedback' then array['content','response'] when 'incident_reports' then array['response'] when 'appointments' then array['purpose','cancellation_reason','admin_notes'] when 'announcements' then array['title','message'] when 'remarks' then array['remark_text'] when 'community_case_updates' then array['message'] else array[]::text[] end;
 foreach field in array fields loop
   if (tg_op='INSERT' or new_row->>field is distinct from old_row->>field) and private.contains_profanity(new_row->>field) then
     label:=case field when 'body' then 'Message' when 'content' then 'Feedback' when 'response' then 'Response' when 'purpose' then 'Request details' when 'cancellation_reason' then 'Cancellation reason' when 'admin_notes' then 'Administrator notes' when 'title' then 'Announcement title' when 'remark_text' then 'Review remarks' when 'message' then case when tg_table_name='announcements' then 'Announcement text' else 'Progress update' end end;
     raise exception '%: Please revise the offensive English or Tagalog wording before sending. Your text has been kept so you can edit it.',label using errcode='22023';
   end if;
 end loop;
 return new;
end $$;
revoke all on function private.moderate_community_text() from public,anon,authenticated;
